<section class="game-hero"><div><span class="eyebrow">GAME</span><h1><?=e($game['name'])?></h1><p class="lead"><?=e($game['description'])?></p><div class="meta"><span><?=count($updates)?> tracked updates</span><span>Source-backed</span></div></div><div class="cover" style="background-image:url('<?=e($game['image_url']?:'https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1200&q=80')?>')"></div></section><section class="section game-history"><div class="section-head"><div><h2>Update history</h2><p class="muted">Original Steam formatting is preserved where available.</p></div><span class="muted">Newest first</span></div><div class="timeline"><?php foreach($updates as $u):?><article class="update-entry"><div class="dot"></div><div class="update-card"><div class="update-meta"><span><?=date('j M Y · H:i',strtotime($u['published_at']))?></span><span><?=e($u['source_name'])?></span><?php if($u['verified']):?><span class="verified">VERIFIED</span><?php endif;?></div><h3><?=e($u['title'])?></h3><div class="steam-update-body"><?=function_exists('display_update_body')?display_update_body((string)($u['body']??''),(string)($u['body_format']??'text')):nl2br(e((string)($u['body']??'')))?></div><?php if($u['source_url']):?><a class="source" href="<?=e($u['source_url'])?>" target="_blank" rel="noopener noreferrer">View original source ↗</a><?php endif;?></div></article><?php endforeach;if(!$updates):?><div class="empty">No updates yet.</div><?php endif;?></div></section>